/**
 * 특정 월의 인덱스 조회
 * @param year 양력 년
 * @param month 양력 월
 * @returns 월별 인덱스 또는 undefined
 */
export function getMonthlyIndex(year: number, month: number): MonthlyIndex | undefined {
  const key = `${year}-${String(month).padStart(2, '0')}`;
  return SOLAR_TO_LUNAR_INDEX.get(key);
}
